module fixed_point_adder #(\n\t//Parameterized values\n\tparameter Q = 15,\n\tparameter N = 32\n\t)\n\t(\n    input [N-1:0] a,\n    input [N-1:0] b,\n    output [N-1:0] c\n    );\n\nreg [N-2:0] magnitude;\nreg sign;\n\nassign c = {sign, magnitude};\n\nalways @* begin\n\t// both negative or both positive\n\tif(a[N-1] == b[N-1]) begin\n\t\tmagnitude = a[N-2:0] + b[N-2:0];\n\t\tsign = a[N-1];\n\tend\n\t// one of them is negative\n\telse if(a[N-1] == 0 && b[N-1] == 1) begin\n\t\tif(a[N-2:0] > b[N-2:0]) begin\n\t\t\tmagnitude = a[N-2:0] - b[N-2:0];\n\t\t\tsign = 0;\n\t\tend\n\t\telse begin\n\t\t\tmagnitude = b[N-2:0] - a[N-2:0];\n\t\t\tif(magnitude == 0)\n\t\t\t\tsign = 0;\n\t\t\telse\n\t\t\t\tsign = 1;\n\t\tend\n\tend\n\telse begin\n\t\tif(a[N-2:0] > b[N-2:0]) begin\n\t\t\tmagnitude = a[N-2:0] - b[N-2:0];\n\t\t\tif(magnitude == 0)\n\t\t\t\tsign = 0;\n\t\t\telse\n\t\t\t\tsign = 1;\n\t\tend\n\t\telse begin\n\t\t\tmagnitude = b[N-2:0] - a[N-2:0];\n\t\t\tsign = 0;\n\t\tend\n\tend\nend\nendmodule
